"body": [
"إذا سمعتَ كلمةَ «علم» قد تواجهُ في حياتِك مشاكلَ عليك حلُّها، أو أسئلةً تحتاجُ إلى إجابات؛ <b>فالعلمُ</b> طريقةٌ أو عمليةٌ تستخدمُها في استقصاءِ ما يجري حولَك، ويعينُك على توفيرِ إجاباتٍ لأسئلتِك.",
"حاولَ الناسُ عبر التاريخِ تفسيرَ ما يحدثُ للأشياءِ حولَهم، معتمدين على ملاحظاتِهم التي توصّلوا إليها عن طريقِ حواسِّهم الخمس. وقد عرفتَ من التجربةِ الاستهلاليةِ أنّ استخدامَ الحواسِّ فقط قد يؤدّي إلى فهمٍ غيرِ دقيق؛ فإنْ وصفتَ شيئًا بأنّه باردٌ أو ساخنٌ فإنّك لم تحدّدْ درجةَ حرارتِه.",
"تُستخدَمُ الأرقامُ في وصفِ الملاحظات، وتُستخدَمُ أدواتٌ منها مقياسُ الحرارةِ والمساطرُ المتريةُ لإعطاءِ قيمٍ رقميةٍ لهذا الوصف؛ حيث يلاحظُ العلماءُ ويستقصون ويجرّبون للتوصّلِ إلى إجابات، ويمكنُك أنت أيضًا أن تقومَ بذلك."
],
