"t": "كلّفَ المعلّمُ الطالبين أحمد وبدر بإعدادِ مشروعٍ يوضّحُ أوجهَ التشابهِ والاختلافِ بين حدثٍ في الماضي وشيءٍ يحدثُ في مجتمعِنا الحاضر؛ فقرأا في صحفٍ قديمةٍ قصصًا حول تفشّي وباءِ الكوليرا الذي أدّى إلى وفاةِ عشرةِ أشخاصٍ وإصابةِ ٥٠ آخرين عام ١٨٧١م، ويشبهُه تفشّي بكتيريا القولون (E.coli) في مدينتِنا الآن."
