"body": [
"كلّفَ المعلّمُ الطالبين أحمد وبدر بإعدادِ مشروعٍ يوضّحُ أوجهَ التشابهِ والاختلافِ بين حدثٍ في الماضي وشيءٍ يحدثُ في مجتمعِنا الحاضر؛ فقرأا في صحفٍ قديمةٍ قصصًا حول تفشّي وباءِ <b>الكوليرا</b> الذي أدّى إلى وفاةِ عشرةِ أشخاصٍ وإصابةِ ٥٠ آخرين عام ١٨٧١م، ويشبهُه تفشّي بكتيريا <b>القولون (E.coli)</b> في مدينتِنا الآن.",
"الكوليرا مرضٌ تسبّبُه بكتيريا توجدُ في الماءِ الملوّث، ويُصابُ الأشخاصُ الذين يستخدمون هذا الماءَ بإسهالٍ شديدٍ وجفافٍ قد يؤدّي إلى الموتِ أحيانًا. أمّا بكتيريا القولون فهي نوعٌ آخرُ من البكتيريا؛ بعضُها غيرُ ضارّ، وبعضُها الآخرُ قد يسبّبُ مشاكلَ معويةً نتيجةَ تلوّثِ الغذاءِ والماء.",
"<b>العلماءُ يستخدمون الأدلّة</b>: يفعلُ العلماءُ الشيءَ نفسَه في نواحٍ كثيرة؛ ففي عام ١٨٧١م تتبّعَ العلماءُ دليلًا لمعرفةِ مصدرِ وباءِ الكوليرا لحلِّ مشكلتِهم، واليومَ يفعلُ العلماءُ الشيءَ نفسَه لتتبّعِ بكتيريا القولون والبحثِ عن مصدرِها.",
"<b>استخدامُ المعرفةِ السابقة</b>: يستفيدُ العلماءُ من الخبراتِ السابقةِ ليتوقّعوا ما يحدثُ في أثناءِ الاستقصاءات، وبذلك يضعون النظرياتِ بعد اختبارِ التوقّعاتِ جيّدًا. و<b>النظريةُ</b> تفسيرٌ للأشياءِ مدعومٌ بالحقائق. كما يضعون <b>القوانين</b>، وهي قواعدُ تصفُ نمطًا في الطبيعة، ومن أمثلتِها قوانينُ الجاذبية."
],
