"<b>التواصلُ في العلم</b>: يستخدمُ العلماءُ عدّةَ طرائقَ لإيصالِ ملاحظاتِهم إلى الآخرين، وغالبًا ما تُوثَّقُ نتائجُ التجاربِ في المجلّاتِ العلميةِ التي تُنشَرُ دوريًّا. و<b>دفترُ العلوم</b> طريقةٌ أخرى للتواصل؛ تُسجَّلُ فيه الملاحظاتُ وخططُ الاستقصاءاتِ والخطواتُ والموادُّ والأدواتُ والنتائجُ والجداولُ والرسومُ البيانية."
