"<b>تحديدُ هدفِ البحث</b>: هدفُ البحثِ هو ما تريدُ أن تكتشفَه، أو السؤالُ الذي ترغبُ في الإجابةِ عنه. فقد كان هدفُ أحمد وبدر اكتشافَ كيف تمَّ تتبّعُ مصدرِ وباءِ الكوليرا وبكتيريا القولون، وحدّدَ الدكتورُ جون سنو هدفَه وهو اكتشافُ مصدرِ الكوليرا في لندن."
