"body": [
"<b>وصفُ تصميمِ البحث</b>: كيف تنفّذُ استقصاءَك؟ وما الخطواتُ التي ستتّبعُها؟ وكيف ستسجّلُ بياناتِك أو تحلّلُها؟ هذه بعضُ الأسئلةِ التي يفكّرُ فيها العلماءُ عندما يصمّمون استقصاءً بطريقةِ البحثِ الوصفي. وتُعدُّ احتياطاتُ السلامةِ أهمَّ جزءٍ في تصميمِ أيِّ بحث.",
"لقد ضمّنَ الدكتورُ جون سنو بحثَه خريطةً توضّحُ أماكنَ سكنِ المرضى المصابين بالكوليرا، وأماكنَ حصولِهم على الماء؛ واستخدمَ هذه البياناتِ في توقّعِ أنّ مياهَ المضخّةِ اليدويةِ الموجودةِ في الشارعِ – كما في الشكل ١٠ – كانت مصدرَ التلوّث.",
"<b>الموضوعية</b>: عندما يتوقّعُ العلماءُ نتائجَ معيّنةً قبل إجراءِ الاستقصاء يُعدُّ هذا تحيّزًا؛ فالاستقصاءُ الجيّدُ يتفادى التحيّز. ومن طرائقِ تفادي التحيّزِ تحويلُ جميعِ البياناتِ إلى قياساتٍ رقمية، واستخدامُ عيّنةٍ عشوائيةٍ للحصولِ على نتيجةٍ دقيقة.",
"<b>اختيارُ الموادِّ والأجهزة</b>: يفضّلُ أن تستخدمَ الأجهزةَ العلميةَ مثلَ الميزانِ ذي الكفّتين والموازينِ ذاتِ النوابضِ والمجاهر، وتساعدُ الآلاتُ الحاسبةُ والحواسيبُ على عرضِ البياناتِ وإجراءِ الحساباتِ عليها. وليس من الضروريِّ استخدامُ موادَّ مطوّرةٍ جدًّا أو باهظةِ الثمن.",
"<b>استخدامُ النماذج</b>: <b>النموذجُ</b> يمثّلُ أشياءَ تحدثُ ببطءٍ شديدٍ أو بسرعةٍ كبيرة، أو يمثّلُ أشياءَ كبيرةً جدًّا أو صغيرةً جدًّا يصعبُ ملاحظتُها مباشرة، أو عاليةَ التكلفةِ أو خطرة. وتساعدُ الحواسيبُ على إعدادِ نماذجَ ثلاثيةِ الأبعادِ للمجسّماتِ المجهرية، أو نيزكٍ ضخم، أو بركانٍ ثائر، أو تصميمِ الطائراتِ والمباني."
],
