"t": "القياساتُ العلمية: يستخدمُ العلماءُ لجمعِ الملاحظاتِ في جميعِ أنحاءِ العالمِ نظامًا للقياسِ يُسمّى النظامَ العالميَّ للوحدات (SI)؛ ممّا يسهّلُ فهمَ نتائجِ البحوثِ ومقارنتَها بعضِها ببعض. انظرْ إلى الجدول ١ الذي يوضّحُ معظمَ الوحداتِ التي ستستخدمُها في دراستِك للعلوم."
