"body": [
"<b>القياساتُ العلمية</b>: يستخدمُ العلماءُ لجمعِ الملاحظاتِ في جميعِ أنحاءِ العالمِ نظامًا للقياسِ يُسمّى <b>النظامَ العالميَّ للوحدات (SI)</b>؛ ممّا يسهّلُ فهمَ نتائجِ البحوثِ ومقارنتَها بعضِها ببعض. انظرْ إلى الجدول ١ الذي يوضّحُ معظمَ الوحداتِ التي ستستخدمُها في دراستِك للعلوم.",
"يستخدمُ العلماءُ أدواتٍ للقياس؛ فيُستخدَمُ <b>المخبارُ المدرّجُ</b> لقياسِ حجمِ السائل، و<b>الميزانُ</b> لقياسِ الكتلة، بينما يُستخدَمُ <b>مقياسُ الحرارة</b> لقياسِ درجةِ الحرارة (الشكل ١٢).",
"<b>البيانات</b>: يجبُ أن تُجمَعَ البياناتُ في البحوثِ العلميةِ وتُنظَّمَ بصورةٍ صحيحة؛ فالتنظيمُ الجيّدُ للبياناتِ يسهّلُ عمليتي التفسيرِ والتحليل. ومن الطرائقِ جداولُ البيانات؛ ولكلِّ جدولٍ عنوانٌ يعبّرُ عن مضمونِه، ويُقسَمُ إلى أعمدةٍ وصفوف.",
"<b>تحليلُ البيانات</b>: بعد الانتهاءِ من تنفيذِ الاستقصاءِ ينبغي مراجعةُ جميعِ الملاحظاتِ والقياساتِ التي سجّلتَها، وأن تكونَ بياناتُك منظّمةً جيّدًا لتحليلِها. ولأنّ الرسومَ البيانيةَ على اختلافِ أنواعِها من أفضلِ الطرائقِ لتنظيمِ البيانات، فإنّه يمكنُك أن تمثّلَ هذه البياناتِ بالرسومِ البيانية (الشكل ١٣)."
],
