"t": "التجريبُ عملٌ أساسٌ في العلوم، والبحوثُ التي تعتمدُ على التجريبِ تساعدُ على الإجابةِ عن أسئلةٍ علميةٍ من خلالِ ملاحظةِ حالاتٍ قابلةٍ للتحكّمِ فيها وضبطِها. ويبدأُ تصميمُ البحثِ التجريبيِّ بـتكوينِ فرضية؛ والفرضيةُ توقّعٌ أو عبارةٌ قابلةٌ للاختبار."
