"t": "لتختبرَ أيُّ المضادّين الحيويين يقتلُ البكتيريا تأكّدْ أنّ كلَّ العواملِ ثابتةٌ ما عدا نوعَ المضادِّ الحيوي؛ وتُسمّى المتغيّراتُ التي تبقى ثابتةً دون أن تتغيّرَ الثوابت؛ فلا يمكنُك إجراءُ التجربةِ في درجاتِ حرارةٍ مختلفة أو فتراتٍ زمنيةٍ مختلفة."
