"body": [
"تتعرّضُ الصخورُ رغمَ صلابتِها لقوى السحبِ أو الدفع، فيتغيّرُ شكلُها قليلًا كما يحدثُ لغصنِ الشجرةِ عند ثنيه، ثم تعودُ حوافُّ الأجزاءِ المكسورةِ سريعًا إلى مكانِها الأصلي. تُسمّى هذه العمليةُ <b>الارتدادَ المرن</b>.",
"تتغيّرُ أشكالُ الصخورِ عادةً أو تتشوّهُ ببطءٍ خلال فتراتٍ زمنيةٍ طويلة؛ فمع تعرّضِ الصخورِ للإجهاداتِ تتراكمُ الطاقةُ داخلَها، ثم تتحرّرُ هذه الطاقةُ فجأةً نتيجةَ تكسّرِ الصخورِ وتحرّكِها.",
"تؤدّي هذه التكسّراتُ والحركاتُ إلى حدوثِ اهتزازاتٍ تنتقلُ خلالَ الصخرِ أو أيِّ مادّةٍ في الأرض، فإذا كانت كبيرةً نحسُّ بها على هيئةِ <b>زلزال</b>."
],
