"تُرسَمُ دائرةٌ حولَ كلِّ محطةِ رصدٍ نصفُ قطرِها يساوي بُعدَ الزلزالِ عنها، ويتكرّرُ هذا لثلاثِ محطاتٍ على الأقلّ (الشكل ٦)، فتحدّدُ النقطةُ التي تلتقي عندها الدوائرُ الثلاث موقعَ المركزِ السطحيِّ للزلزال."
