"في ١١/٣/٢٠١١م ضربَ اليابانَ زلزالٌ قوتُه <b>٨٫٩</b> على مقياسِ رختر، وأدّى إلى موجاتِ تسونامي وصلَ ارتفاعُها إلى أكثرَ من ١٠ أمتار. وتُعدُّ اليابانُ من أكثرِ مناطقِ العالمِ نشاطًا زلزاليًّا؛ إذ يحدثُ فيها نحو ٢٠٪ من زلازلِ العالمِ التي تزيدُ قوتُها على ٦ درجات.",
