"body": [
"من الأمورِ التي يجبُ اتّباعُها لحمايةِ نفسِك <b>الاطّلاعُ على التاريخِ الزلزاليِّ</b> للمنطقة؛ فإذا كان قد حدثَ زلزالٌ فيها سابقًا فإنّ فرصةَ حدوثِه مجدّدًا ما زالتْ قائمة.",
"ابتعدْ أثناءَ الزلزالِ عن النوافذِ أو أيِّ شيءٍ يمكنُ أن يتساقطَ عليك، وراقبْ كوابلَ الكهرباءِ التي على الأرض، وكنْ حذرًا من الحوافِّ الحادّةِ الناتجةِ عن المباني المنهارة. وضعِ الأجسامَ الثقيلةَ في الرفوفِ المنخفضة (الشكل ٨-أ)، واستخدمْ حسّاساتِ الغازِ التي تقفلُ خطوطَه تلقائيًّا عند الاهتزاز (الشكل ٨-ب).",
"يُعدُّ المبنى <b>آمنًا ضدَّ الزلازل</b> إذا كان قادرًا على مقاومةِ الاهتزازات؛ فقد وُضعتْ معاييرُ للبناءِ في المناطقِ الزلزالية، وشُيّدتْ مبانٍ مرتفعةٌ على دعائمَ مطاطيةٍ وفولاذيةٍ ضخمة، واستُخدمتْ أنابيبُ مرنةٌ للمياهِ والغاز يمكنُ أن تنثني عند الزلزالِ فلا تتكسّر.",
"يحاولُ الباحثون <b>توقّعَ الزلازل</b> بملاحظةِ التغيّراتِ التي تسبقُها، مثل الحركةِ عند الصدوعِ (تُرصَدُ بأجهزةِ الليزر)، والتغيّرِ في منسوبِ المياهِ الجوفية، والخصائصِ الكهربائيةِ لبعضِ الصخور. ولكنْ لا يوجدُ تغيّرٌ واحدٌ ثابتٌ يسبقُ جميعَ الزلازل؛ لذلك لم يتوصّلِ العلماءُ إلى توقّعٍ دقيقٍ لوقتِ حدوثِها.",
"شهدتِ المملكةُ العربيةُ السعوديةُ عدّةَ زلازل، منها <b>زلزالُ العيص</b> في حرّةِ الشاقةِ قربَ المدينةِ المنوّرة، الذي بلغتْ قوتُه ٥٫٨ على مقياسِ رختر، وهو أكبرُ زلزالٍ سُجّلَ رسميًّا على أجهزةِ الرصدِ الزلزاليِّ في المملكة (الشكل ٩). ويرتبطُ ذلك بهدفِ رؤيةِ ٢٠٣٠: ٢.٤.٢ حمايةُ البيئةِ من الأخطارِ الطبيعية."
],
