"body": [
"تُجبَرُ الصهارةُ على الصعودِ إلى سطحِ الأرضِ من قِبَلِ الصخورِ المحيطةِ بها ذاتِ الكثافةِ العالية، وتؤدّي الصهارةُ الصاعدةُ إلى حدوثِ ثورانٍ بركاني، بينما تستمرُّ الغازاتُ في الخروجِ منه.",
"يتشكّلُ في النهايةِ جبلٌ قمعيُّ الشكلِ يُسمّى <b>البركان</b>. وعندما تتدفّقُ الصهارةُ على سطحِ الأرضِ من فوهةِ البركانِ فإنّها تُسمّى <b>اللابة</b>. وتحتوي البراكينُ على فتحاتٍ دائريةٍ عند قممِها تُسمّى فوهةَ البركان.",
"تُلقي بعضُ الثوراناتِ المتفجّرةِ اللابةَ والصخورَ في الهواءِ آلافَ الأمتار، وتُسمّى هذه القطعُ الصخريةُ أو اللابةُ المتصلّبةُ المتساقطةُ <b>المقذوفاتِ الصلبة</b>، ويتراوحُ حجمُها بين غبارٍ ورمادٍ بركانيٍّ وصخورٍ كبيرةٍ تُسمّى قنابلَ بركانية."
],
