"t": "من المخاطرِ التي تنتجُ عن ثورانِ البراكين تدميرُ المدنِ والقرى بسببِ الانهياراتِ والتدفّقاتِ الطينيةِ الملتهبة، وإغلاقُ الموانئِ والمطارات. وقد يصلُ الرمادُ البركانيُّ أثناءَ النشاطِ إلى ارتفاعاتٍ تزيدُ على ١٤٠٠٠ مترٍ في الهواء، ثم يترسّبُ على سطحِ الأرض، وقد يتبعُه حدوثُ تدفّقاتٍ طينيةٍ عند هطولِ أمطارٍ غزيرة."
