"body": [
"اعتُبرَ بركانُ جبلِ سوفريير في جزرِ الكاريبي بركانًا خامدًا، ولكنّه في عام ١٩٩٥م نشطَ فجأة؛ فقذفَ الرمادَ إلى ارتفاعِ أكثرَ من ١٠٠٠٠ مترٍ في الهواء، فغطّى الرمادُ مدينةَ «بلايموث» وعددًا من القرى المجاورة (الشكل ١١-أ).",
"من المخاطرِ التي تنتجُ عن ثورانِ البراكين تدميرُ المدنِ والقرى بسببِ الانهياراتِ والتدفّقاتِ الطينيةِ الملتهبة، وإغلاقُ الموانئِ والمطارات. وقد يصلُ الرمادُ البركانيُّ أثناءَ النشاطِ إلى ارتفاعاتٍ تزيدُ على ١٤٠٠٠ مترٍ في الهواء، ثم يترسّبُ على سطحِ الأرض، وقد يتبعُه حدوثُ تدفّقاتٍ طينيةٍ عند هطولِ أمطارٍ غزيرة.",
"ومن المخاطرِ الأخرى <b>تدفّقُ الفتاتِ البركاني</b>، وهو انهياراتٌ سريعةٌ لصخورٍ حارّةٍ متوهّجةٍ مصحوبةٍ بغازاتٍ حارّة، وقد تصلُ سرعةُ انتقالِ هذه التدفّقاتِ إلى ٢٠٠ كم/ساعة. وقد تتحوّلُ مساحاتٌ شاسعةٌ من الأراضي الخصبةِ إلى أراضٍ قاحلةٍ بسببِ البراكين، ممّا يؤدّي إلى هجرةِ السكّان."
],
