"t": "طوّرَ العلماءُ عام ١٩٦٠م نظريةَ الصفائحِ الأرضيةِ اعتمادًا على فرضياتٍ سابقة، ووُضعتْ لتفسيرِ المعالمِ والأحداثِ الجيولوجيةِ على سطحِ الأرض. وتنصُّ النظريةُ على أنّ الغلافَ الصخريَّ المكوّنَ من القشرةِ الأرضيةِ وأعلى الستار مقسّمٌ إلى قطعٍ يُسمّى كلٌّ منها صفيحة."
