"body": [
"تُسمّى الحدودُ الفاصلةُ بين هذه الصفائحِ <b>حدودَ الصفائح</b>، وهي تُصنَّفُ اعتمادًا على حركةِ الصفائحِ الأرضيةِ إلى: حدودِ تقارب، وحدودِ تباعد، وحدودٍ جانبية (تحويلية).",
"إذا تحرّكتِ الصفائحُ بعضُها نحو بعضٍ فتقاربتْ أو تصادمتْ سُمّيتْ حدودًا <b>متقاربة</b>، أمّا إذا ابتعدَ بعضُها عن بعضٍ فتُسمّى حدودًا <b>متباعدة</b>، وتُسمّى حدودًا <b>جانبيةً</b> إذا تحرّكتِ الصفائحُ أو انزلقَ بعضُها بمحاذاةِ بعض. وينجمُ عن حركةِ الصفائحِ الزلازلُ والبراكين.",
"يتكوّنُ الغلافُ الصخريُّ للأرضِ من ١٣ صفيحةً رئيسة (الشكل ١٥)، وتنتجُ نشاطاتٌ جيولوجيةٌ مهمّةٌ عن تقاربِ الصفائحِ وتباعدِها وانزلاقِها بعضِها بمحاذاةِ بعضٍ عند حدودِها."
],
