"body": [
"عند دراسةِ مواقعِ البراكين ومواقعِ حدودِ الصفائحِ على سطحِ الأرضِ نلاحظُ أنّ معظمَ البراكينِ تتكوّنُ على حدودِ الصفائح (الشكل ١٥).",
"<b>حدودُ الصفائحِ المتباعدة</b>: تتحرّكُ الصفائحُ مبتعدًا بعضُها عن بعض، ومع تباعدِ الصفائحِ تتكوّنُ شقوقٌ طويلةٌ بينها تُسمّى <b>حفرَ الانهدام</b>، وهي تمثّلُ ممرّاتٍ تسهّلُ خروجَ الصهارةِ التي نشأتْ في الستار. ويحدثُ ثورانُ الشقوقِ غالبًا على امتدادِ مناطقِ حفرِ الانهدام، مثلِ حفرةِ الانهدامِ الإفريقيِّ العظيم.",
"<b>حدودُ الصفائحِ المتقاربة</b>: من الأماكنِ الشائعةِ لتكوّنِ البراكين؛ إذ تغوصُ الصفيحةُ المحيطيةُ التي كثافتُها أكبرُ أسفلَ الصفيحةِ الأخرى، فتتشكّلُ البراكينُ المركّبة. ويُسمّى حزامُ البراكينِ الذي يحيطُ بالمحيطِ الهادي <b>بالحزامِ الناريِّ للمحيطِ الهادي</b>.",
"<b>البقعُ الساخنة</b>: تُعدُّ جزرُ هاواي مثالًا على الجزرِ البركانية، ولم تتكوّنْ على حدودِ الصفائح، وإنّما في وسطِ صفيحةِ المحيطِ الهادي؛ فهناك تُجبَرُ كتلٌ كبيرةٌ من الصهارةِ على الصعودِ إلى أعلى خلالَ الستارِ والقشرة، وتُسمّى <b>البقعَ الساخنة</b> (الشكل ١٦)."
],
