"هناك العديدُ من الفرضياتِ حولَ مصدرِ الطاقةِ المحرّكةِ للصفائح؛ تنصُّ إحداها على أنّ مادةَ الستارِ يتمُّ تسخينُها بوساطةِ لبِّ الأرض، فتقلُّ كثافتُها وتصعدُ إلى أعلى، ثم تبردُ هذه المادةُ فتنزلُ إلى أسفلَ في اتجاهِ اللبّ، مكوّنةً <b>تياراتِ الحملِ الحراري</b> في باطنِ الأرض (الشكل ٢٠)، وهي تقدّمُ تفسيرًا لحركةِ الصفائحِ الأرضية.",
"يتركّزُ تأثيرُ حركةِ الصفائحِ في المملكةِ العربيةِ السعوديةِ حولَ حوافِّ الصفيحةِ العربية (الشكل ١٩)؛ حيث تتحرّكُ الصفيحةُ العربيةُ بشكلٍ دورانيٍّ في اتجاهِ الشمالِ الشرقي؛ لذا فإنّ حدوثَ الزلازلِ والبراكينِ مرتبطٌ مع هذه الحواف.",
"يتركّزُ النشاطُ الزلزاليُّ في المملكةِ على امتدادِ البحرِ الأحمرِ وحتى خليجِ العقبة، حيث تمثّلُ هذه المناطقُ حدودَ تباعدٍ بين الصفيحةِ العربيةِ والصفيحةِ الإفريقية، كما أنّ هناك بعضَ النشاطِ الزلزاليِّ حولَ بعضِ الحِرارِ البركانية.",
"أمّا النشاطُ البركانيُّ فيرتبطُ عادةً مع حركةِ الصفيحةِ العربية؛ لذا فإنّ النشاطَ البركانيَّ في المملكةِ يتركّزُ في الجهةِ الغربيةِ على امتدادِ ساحلِ البحرِ الأحمر، ويوجدُ في المملكةِ ١٢ حرّةً بركانية، من أهمِّها حرّةُ رهط بالمدينةِ المنوّرة، وحرّةُ الشاقة."
