"body": [
"يحيطُ بالخليةِ <b>الغشاءُ البلازميُّ</b> الذي يشبهُ في عملِه شبكَ النافذة، ويمتازُ <b>بالنفاذيةِ الاختيارية</b>؛ حيث يسمحُ لبعضِ الموادِّ بالنفاذِ من الخليةِ وإليها، بينما يمنعُ موادَّ أخرى من المرور.",
"تستطيعُ الموادُّ المرورَ خلالَ الغشاءِ البلازميِّ بطرائقَ مختلفة، تعتمدُ على حجمِ الجزيئات، والطريقِ الذي تسلكُه، وحاجتِها إلى الطاقة. وتُسمّى عمليةُ نقلِ الموادِّ عبر الغشاءِ البلازميِّ دون الحاجةِ إلى الطاقةِ <b>النقلَ السلبي</b>، وهناك ثلاثةُ أنواعٍ منه: الانتشار، والخاصيةُ الأسموزية، والانتشارُ المدعوم.",
"<b>الانتشار</b>: قد تشمُّ رائحةَ عطرٍ عندما يجلسُ أحدُهم إلى جوارِك؛ لأنّ جزيئاتِ العطرِ تتحرّكُ عشوائيًّا في الهواء. وتُسمّى عمليةُ انتقالِ الجزيئاتِ من الأماكنِ ذاتِ التركيزِ المرتفعِ إلى الأماكنِ ذاتِ التركيزِ المنخفضِ الانتشار.",
"يستمرُّ الانتشارُ حتى يصبحَ العددُ النسبيُّ للجزيئاتِ متساويًا في المنطقتين، وعندها نصلُ إلى حالةِ <b>الاتزان</b>، وتتوقّفُ هذه العملية. فعندما يضخُّ القلبُ الدمَ إلى الرئتين تكونُ خلايا الدمِ الحمراءُ محمّلةً بكمياتٍ قليلةٍ من الأكسجين، بينما تحتوي الرئتان على كمياتٍ كبيرةٍ منه، فتنتقلُ جزيئاتُ الأكسجينِ بالانتشارِ إلى خلايا الدمِ الحمراء، ثم تنتقلُ منها إلى خلايا إصبعِ القدم (الشكل ٢)."
],
