"t": "درستَ سابقًا أنّ الماءَ يشكّلُ جزءًا كبيرًا من المادةِ الحيّة، وأنّه يملأُ الخلايا ويحيطُ بها. تتحرّكُ جزيئاتُ الماءِ داخلَ الخليةِ وخارجَها عبر الغشاءِ البلازميِّ عن طريقِ الانتشار، ويطلقُ العلماءُ على عمليةِ انتشارِ الماءِ الخاصيةَ الأسموزية."
