"تحتاجُ الخليةُ إلى الطاقةِ لنقلِ الموادِّ عبر غشائِها، وتُسمّى عملياتُ النقلِ هذه <b>النقلَ النشط</b>. وتحتاجُ عمليةُ النقلِ النشطِ إلى بروتيناتٍ ناقلة؛ تتّحدُ الموادُّ المنقولةُ مع البروتيناتِ الناقلة، وتستهلكُ البروتيناتُ الطاقةَ لنقلِها عبر الغشاءِ البلازمي، ويمكنُ أن ترتبطَ بجزيئاتٍ أخرى تنقلُها عبر الغشاءِ من جديد.",
"<b>البلعمةُ والإخراجُ الخلوي</b>: تكونُ بعضُ الجزيئاتِ كبيرةً جدًّا بحيث لا يمكنُ نقلُها بالانتشارِ أو بالبروتيناتِ الناقلة، مثلُ جزيئاتِ البروتيناتِ الضخمةِ والبكتيريا؛ فيحيطُ بها الغشاءُ البلازميُّ وينغلقُ على نفسِه مكوّنًا كرةً تُسمّى الفجوة. وتُسمّى هذه العمليةُ <b>البلعمة</b>، وتحصلُ بعضُ المخلوقاتِ الوحيدةِ الخليةِ على غذائِها بهذه الطريقة كالأميبا (الشكل ٥).",
"تستطيعُ الفجواتُ إخراجَ محتوياتِها خلالَ عمليةٍ تُسمّى <b>الإخراجَ الخلوي</b>، وهي عكسُ عمليةِ البلعمة؛ حيث تندمجُ الفجوةُ مع الغشاءِ البلازمي فتنطلقُ محتوياتُ الفجوةِ إلى خارجِ الخلية. وتستعملُ خلايا المعدةِ هذه الطريقةَ لإطلاقِ الموادِّ الكيميائيةِ التي تساعدُ على هضمِ الطعام (الشكل ٦)."
