"t": "دورةُ الخلية: قدّرَ الحقُّ تباركَ وتعالى لجميعِ المخلوقاتِ الحيّةِ أن تمرَّ بمراحلَ متتابعةٍ خلالَ حياتِها، وهذا ما يُعرَفُ بدورةِ الحياة. ويُقصَدُ بدورةِ الخليةِ المراحلُ أو الأطوارُ المتتابعةُ التي تمرُّ بها الخليةُ منذ بدءِ الانقسامِ الخلويِّ حتى الانقسامِ الخلويِّ الذي يليه (الشكل ١٣)."
