"body": [
"يستمرُّ الانقسامُ الخلويُّ حتى بعد توقّفِ النمو؛ فهو يعوّضُ الخلايا التالفة؛ فعلى سبيلِ المثال، خلالَ اللحظاتِ التي تستغرقُها لقراءةِ هذه الجملة يُنتجُ نخاعُك العظميُّ ستّةَ ملايينِ خليةِ دمٍ حمراء. وللانقسامِ الخلويِّ أهميةٌ أيضًا للمخلوقاتِ الحيّةِ الوحيدةِ الخلية؛ فهي تتكاثرُ عن طريقِ الانقسامِ الخلوي.",
"<b>دورةُ الخلية</b>: قدّرَ الحقُّ تباركَ وتعالى لجميعِ المخلوقاتِ الحيّةِ أن تمرَّ بمراحلَ متتابعةٍ خلالَ حياتِها، وهذا ما يُعرَفُ بدورةِ الحياة. ويُقصَدُ بدورةِ الخليةِ المراحلُ أو الأطوارُ المتتابعةُ التي تمرُّ بها الخليةُ منذ بدءِ الانقسامِ الخلويِّ حتى الانقسامِ الخلويِّ الذي يليه (الشكل ١٣).",
"تختلفُ المدّةُ التي تستغرقُها دورةُ الخليةِ من خليةٍ إلى أخرى؛ فمثلًا تستغرقُ دورةُ حياةِ بعضِ خلايا نباتِ الفول ١٩ ساعة، بينما نجدُ أنّ خلايا أجنّةِ الحيواناتِ تنقسمُ بسرعةٍ بحيث تكملُ دورتَها في أقلَّ من ٢٠ دقيقة، أمّا في جسمِ الإنسانِ فإنّ دورةَ حياةِ بعضِ الخلايا تستغرقُ ١٦ ساعة.",
"<b>الطورُ البيني</b> يشكّلُ معظمَ زمنِ دورةِ الخليةِ الحقيقيةِ النواة، وتستغرقُه الخليةُ في النمو؛ فالخلايا التي لا تنقسمُ في الجسم – ومنها الخلايا العصبيةُ والعضلية – تبقى في هذا الطور. أمّا الخلايا النشطةُ – ومنها خلايا الجلد – فتنسخُ المادةَ الوراثيةَ استعدادًا للانقسامِ الخلوي؛ لكي تحصلَ كلُّ خليةٍ جديدةٍ على نسخةٍ كاملةٍ من المادةِ الوراثية."
],
