"t": "تُسمّى عمليةُ انقسامِ النواةِ إلى نواتين متماثلتين الانقسامَ المتساويَ (غيرَ المباشر)، وتكونُ النواةُ الجديدةُ مماثلةً للنواةِ الأصلية. ويتضمّنُ سلسلةً من الأطوارِ المتتالية: الطورُ التمهيدي، والطورُ الاستوائي، والطورُ الانفصالي، والطورُ النهائي."
