"t": "تلعبُ الكروموسومات دورًا مهمًّا في عمليةِ انقسامِ النواة؛ والكروموسومُ تركيبٌ في النواةِ يحتوي على المادةِ الوراثية. وخلالَ الطورِ البينيِّ يتضاعفُ كلُّ كروموسوم، فيظهرُ في صورةِ سلسلتين متماثلتين تُسمّى كلُّ واحدةٍ منهما كروماتيدًا، وترتبطان معًا في منطقةٍ تُسمّى السنترومير (الشكل ١٤)."
