"a": "الكروموسومُ يتضاعفُ في الطورِ البينيِّ فيتكوّنُ من كروماتيدين متماثلين مرتبطين بالسنترومير، وعندما ينفصلان في الطورِ الانفصاليِّ يُسمّى كلٌّ منهما كروموسومًا."
