"t": "التكاثرُ الجنسيّ يتطلّبُ وجودَ فردين؛ وخلالَه تتّحدُ البويضةُ وهي الخليةُ الجنسيةُ الناتجةُ عن الأعضاءِ التناسليةِ الأنثوية، مع الحيوانِ المنوي وهو الخليةُ الجنسيةُ الناتجةُ عن الأعضاءِ التناسليةِ الذكرية (الشكل ٢٠). وتُعرَفُ هذه العمليةُ بالإخصاب، وتُسمّى الخليةُ الناتجةُ البويضةَ المخصبةَ أو الزيجوت، وتمرُّ بعده بسلسلةٍ من الانقسامِ المتساويِ والانقسامِ الخلويِّ فيُنتَجُ فردٌ جديد."
