"<b>الخلايا الأحاديةُ المجموعةِ الكروموسومية</b>: يكونُ عددُ الكروموسوماتِ في الخلايا الجنسيةِ نصفَ عددِها في الخلايا الجسمية؛ لذا نقولُ إنّها أحاديةُ المجموعةِ الكروموسومية (Haploid)، فمثلًا يكونُ عددُ الكروموسوماتِ في الخلايا الجنسيةِ في الإنسانِ ٢٣ كروموسومًا فقط (كروموسومٌ واحدٌ من كلِّ زوجٍ من الكروموسوماتِ المتشابهة)."
