"t": "تستعملُ الخليةُ الشفراتِ المختزنةَ في مادتِها الوراثية، والتي تكونُ على صورةِ مركّبٍ كيميائيٍّ يُسمّى الحمضَ النوويَّ المنقوصَ الأكسجين أو DNA، الذي يحوي معلوماتٍ خاصّةً بنموِّ ونشاطِ المخلوقاتِ الحيّة. وعندما تنقسمُ الخليةُ يتضاعفُ DNA وينتقلُ إلى الخلايا الجديدة؛ فكلُّ خليةٍ تتكوّنُ في جسمِك أو في جسمِ أيِّ مخلوقٍ حيٍّ آخر تحتوي على DNA."
