"t": "نسخُ DNA: عندما تتضاعفُ الكروموسوماتُ قبلَ الانقسامِ المنصّفِ أو المتساوي تتضاعفُ كميةُ DNA داخلَ النواة. وقد أظهرَ نموذجُ واطسون وكريك كيف يحدثُ ذلك؛ حيث تنفصلُ السلسلتان في DNA إحداهما عن الأخرى بمساعدةِ إنزيمٍ معيّن، ثم ترتبطُ قواعدُ نيتروجينيةٌ جديدةٌ بالقواعدِ الأصلية، فيتكوّنُ DNA جديدٌ يحملُ ترتيبَ القواعدِ النيتروجينيةِ نفسَه في DNA الأصلي (الشكل ٢)."
