"body": [
"هل تشبهُ أحدَ والديك أم جدّيك؟ إنّ صفاتِ العيونِ وشكلِ الأنفِ وغيرِها أمثلةٌ على الصفاتِ التي ترثُها من والديك. <b>فالوراثةُ</b> هي انتقالُ الصفاتِ الوراثيةِ من الآباءِ إلى الأبناء.",
"<b>ما علمُ الوراثة؟</b> تتحكّمُ الجيناتُ المحمولةُ على الكروموسوماتِ في شكلِ المخلوقِ الحيِّ ووظائفِه، أي في ما نسمّيه صفاتِه الوراثية. وتُسمّى أزواجُ الجيناتِ المسؤولةُ عن صفةٍ محدّدةٍ <b>الجيناتِ المتقابلة (الأليل)</b>.",
"تنفصلُ الجيناتُ المتقابلةُ بعضُها عن بعضٍ أثناءَ انفصالِ الكروموسوماتِ خلالَ عمليةِ الانقسامِ المنصّف، وتتوزّعُ على الخلايا الجنسيةِ الناتجة، بحيث تحصلُ كلُّ خليةٍ على أحدِ الجيناتِ المتقابلة؛ فلو درسنا صفةً محدّدةً مثلَ وجودِ الغمّازات (الشكل ٨) لوجدنا أنّ إحدى الخليتين الجنسيتين الناتجتين عن الانقسامِ المنصّفِ تحتوي على جينِ وجودِ الغمّازات، في حين تحتوي الأخرى على جينٍ يخلو منها.",
"إنّ دراسةَ كيفيةِ انتقالِ الصفاتِ الوراثيةِ وتفاعلِها فيما بينها هو ما يُعرَفُ <b>بعلمِ الوراثة</b>."
],
