"t": "هل تصدّقُ أنّ التجاربَ على نباتِ البازلاءِ هي التي ساعدتِ العلماءَ على فهمِ سببِ ظهورِ عيونِنا بألوانِها المتعدّدة؟ درسَ جريجور مندل – وهو عالمٌ نمساويُّ الرياضياتِ والعلوم – وبدأَ اهتمامُه بالنباتاتِ منذ طفولتِه في بستانِ والدِه، وبدأَ تجاربَه على نباتِ البازلاءِ عام ١٨٥٦م."
