"t": "دورُ الاحتمالاتِ في توقّعِ الصفات: الاحتمالاتُ فرعٌ من فروعِ الرياضيات، تساعدُ على توقّعِ فرصةِ حدوثِ شيءٍ ما؛ فإذا رميتَ قطعةَ نقدٍ في الهواءِ فإنّ احتمالَ ظهورِ الصورةِ ٥٠٪. ولجأَ مندل إلى الاحتمالاتِ في تفسيرِ نتائجِه، ونظرًا إلى أنّه كان يحصلُ على أعدادٍ كبيرةٍ من النباتاتِ لدراسةِ الصفةِ الواحدةِ كانت نتائجُه دقيقةً جدًّا؛ فخلالَ ثماني سنواتٍ درسَ مندل ٣٠٠٠٠ نبتةِ بازلاءٍ تقريبًا."
