"t": "الجيناتُ المتقابلةُ تحدّدُ الصفاتِ الوراثية: تحتوي معظمُ الخلايا على جينين متقابلين على الأقلِّ للصفةِ الوراثيةِ الواحدة، محمولةٍ على أزواجِ الكروموسوماتِ المتماثلة؛ فإذا كان للمخلوقِ الحيِّ جينان متقابلان متماثلان نقولُ إنّ لديه جيناتٍ متماثلة، فإنّها تُكتبُ TT (متماثلُ الجيناتِ لصفةِ طولِ الساق) أو tt (متماثلُ الجيناتِ لصفةِ قصرِ الساق). أمّا المخلوقُ الذي لديه جينان متقابلان مختلفان فنقولُ إنّ لديه جيناتٍ غيرَ متماثلة Tt."
