"t": "أطلقَ الفلاسفةُ القدماءُ على الجسيماتِ التي لا يمكنُ تقسيمُها اسمَ الذرّات. لكنّهم لم يحاولوا إثباتَ نظرياتِهم بالتجاربِ العمليةِ كما يفعلُ العلماءُ اليوم؛ فقد كانت نظرياتُهم نتيجةَ التفكيرِ المجرّدِ والجدلِ والمناقشات دون أيِّ دليلٍ أو برهان. أمّا العلماءُ اليومَ فلا يقبلون نظريةً غيرَ مدعومةٍ بالدليلِ التجريبي."
