"t": "لا يقبلُ العلماءُ أيَّ نموذجٍ ما لم يتمَّ اختبارُه. بدأَ رذرفورد ومساعدوه عام ١٩٠٦م اختبارَ صحّةِ نموذجِ طومسون، فأرادوا معرفةَ ما يحدثُ عند إطلاقِ جسيماتِ ألفا – وهي جسيماتٌ موجبةٌ سريعة – لتصطدمَ بمادةٍ مثلِ صفيحةٍ رقيقةٍ من الذهب سُمكُها ٤٠٠ نانومتر، محاطةٍ بشاشةٍ فلوريسنتيةٍ تتوهّجُ بالضوءِ عند سقوطِ جسيماتٍ مشحونةٍ عليها (الشكل ٩)."
