"t": "نتائجُ متوقّعة: كان رذرفورد واثقًا من نتائجِ التجربة، حيث توقّعَ أنّ معظمَ جسيماتِ ألفا السريعةِ ستمرُّ من خلالِ الصفيحةِ لتصطدمَ بالشاشةِ في الطرفِ المقابلِ تمامًا، كما تخترقُ الرصاصةُ لوحًا من الزجاج؛ لأنّ صفيحةَ الذهبِ في نموذجِ طومسون لا توجدُ فيها كميةٌ كافيةٌ من المادةِ لإيقافِ جسيماتِ ألفا (الشكل ١٠)."
