"body": [
"لا يقبلُ العلماءُ أيَّ نموذجٍ ما لم يتمَّ اختبارُه. بدأَ <b>رذرفورد</b> ومساعدوه عام ١٩٠٦م اختبارَ صحّةِ نموذجِ طومسون، فأرادوا معرفةَ ما يحدثُ عند إطلاقِ <b>جسيماتِ ألفا</b> – وهي جسيماتٌ موجبةٌ سريعة – لتصطدمَ بمادةٍ مثلِ صفيحةٍ رقيقةٍ من الذهب سُمكُها ٤٠٠ نانومتر، محاطةٍ بشاشةٍ فلوريسنتيةٍ تتوهّجُ بالضوءِ عند سقوطِ جسيماتٍ مشحونةٍ عليها (الشكل ٩).",
"<b>نتائجُ متوقّعة</b>: كان رذرفورد واثقًا من نتائجِ التجربة، حيث توقّعَ أنّ معظمَ جسيماتِ ألفا السريعةِ ستمرُّ من خلالِ الصفيحةِ لتصطدمَ بالشاشةِ في الطرفِ المقابلِ تمامًا، كما تخترقُ الرصاصةُ لوحًا من الزجاج؛ لأنّ صفيحةَ الذهبِ في نموذجِ طومسون لا توجدُ فيها كميةٌ كافيةٌ من المادةِ لإيقافِ جسيماتِ ألفا (الشكل ١٠).",
"<b>فشلُ النموذج</b>: صُدمَ رذرفورد عندما جاءَه تلميذُه مندفعًا ليخبرَه أنّ بعضَ جسيماتِ ألفا انحرفَ عن مسارِها بزوايا كبيرة؛ فعبّرَ عن اندهاشِه بقولِه: «إنّ تصديقَنا لذلك يشبهُ تصديقَنا بأنّك أطلقتَ قذيفةً قطرُها ٣٨ سم نحو مجموعةٍ من المناديلِ الورقية، فارتدّتْ عنها وأصابتْك».",
"<b>النموذجُ النوويُّ للذرّة</b>: اقترحَ رذرفورد نموذجًا جديدًا ينصُّ على أنّ معظمَ كتلةِ الذرّةِ وشحنتَها الموجبةَ تتركّزُ في منطقةٍ صغيرةٍ جدًّا في الذرّةِ تُسمّى <b>النواة</b> (الشكل ١١)، وفي عام ١٩٢٠م أطلقَ العلماءُ على الجسيمِ الموجبِ الشحنةِ الذي يوجدُ في نوى جميعِ الذرّاتِ <b>البروتون</b>، بينما بقيةُ حجمِ الذرّةِ فراغٌ يحتوي على إلكتروناتٍ عديمةِ الكتلةِ تقريبًا."
],
