"<b>الحجمُ ومقياسُ الرسم</b>: إنّ رسمَ الذرّةِ النوويةِ بحجمٍ كبيرٍ سابقًا لا يمثّلُ بشكلٍ دقيقٍ حجمَ النواةِ الحقيقيَّ بالنسبةِ إلى الذرّةِ كلِّها؛ فإذا كانت النواةُ بحجمِ كرةِ تنسِ الطاولةِ مثلًا فإنّ الذرّةَ ستكونُ بقطر ٢٫٤ كم.",
