"t": "النظائر: إنّ ذرّاتِ العنصرِ نفسِه يمكنُ أن تختلفَ في أعدادِ النيوتروناتِ في نواها؛ فمعظمُ ذرّاتِ الكربونِ مثلًا تحتوي ستّةَ نيوترونات، بينما يحتوي بعضُها الآخرُ على سبعةٍ أو ثمانيةِ نيوترونات (الشكل ١٦)؛ وتُسمّى هذه الأنواعُ الثلاثةُ النظائر: ذرّاتٌ للعنصرِ نفسِه ولكنّها تحتوي أعدادًا مختلفةً من النيوترونات: كربون-١٢، وكربون-١٣، وكربون-١٤."
