"body": [
"ذرّاتُ العناصرِ المختلفةِ تحتوي على أعدادٍ مختلفةٍ من البروتونات. و<b>العددُ الذرّي</b> لأيِّ عنصرٍ هو عددُ البروتوناتِ الموجودةِ في نواةِ ذرّةِ ذلك العنصر؛ فذرّةُ الهيدروجينِ مثلًا أصغرُ ذرّاتِ العناصر، فهي تحتوي على بروتونٍ واحدٍ في نواتِها، ولذلك فإنّ العددَ الذرّيَّ للهيدروجين هو ١، بينما عنصرُ اليورانيوم أثقلُ العناصرِ الموجودةِ في الطبيعة، وتحتوي نواتُه على ٩٢ بروتونًا. وتُميَّزُ العناصرُ بعضُها عن بعضٍ بعددِ بروتوناتِها؛ لأنّ عددَ البروتوناتِ لا يتغيّرُ إلا بتغيّرِ العنصر.",
"<b>النظائر</b>: إنّ ذرّاتِ العنصرِ نفسِه يمكنُ أن تختلفَ في أعدادِ النيوتروناتِ في نواها؛ فمعظمُ ذرّاتِ الكربونِ مثلًا تحتوي ستّةَ نيوترونات، بينما يحتوي بعضُها الآخرُ على سبعةٍ أو ثمانيةِ نيوترونات (الشكل ١٦)؛ وتُسمّى هذه الأنواعُ الثلاثةُ <b>النظائر</b>: ذرّاتٌ للعنصرِ نفسِه ولكنّها تحتوي أعدادًا مختلفةً من النيوترونات: كربون-١٢، وكربون-١٣، وكربون-١٤.",
"<b>العددُ الكتلي</b>: يمكنُ تعريفُ العددِ الكتليِّ للنظيرِ بأنّه مجموعُ عددِ البروتوناتِ والنيوتروناتِ في نواةِ الذرّة. ويبيّنُ الجدول ١ عددَ الجسيماتِ في كلِّ نظيرٍ من نظائرِ الكربون. ويمكنُ إيجادُ عددِ النيوتروناتِ في كلِّ نظيرٍ بطرحِ العددِ الذرّيِّ من العددِ الكتلي؛ فمثلًا: عددُ النيوتروناتِ في (كربون-١٤) = ١٤ − ٦ = ٨ نيوترونات."
],
