"body": [
"لقد تمَّ تطويرُ عملياتِ التحوّلِ الاصطناعي، وأصبحَ من الممكنِ استخدامُ نظائرِ العناصرِ المشعّةِ المتحوّلةِ من عناصرَ مستقرّةٍ في أجهزةٍ تُستخدمُ في المستشفياتِ والعيادات، وتُسمّى هذه النظائرُ <b>العناصرَ المتتبّعة</b>. وتُستخدمُ في تشخيصِ الأمراضِ ودراسةِ الظروفِ البيئية. ومن المهمِّ معرفةُ أنّ النظائرَ المستخدمةَ في الأغراضِ الطبيةِ لها عمرُ نصفٍ قصير، ممّا يسمحُ لنا باستخدامِها دون الخوفِ من مخاطرِ تعرّضِ المخلوقاتِ الحيّةِ لإشعاعاتٍ طويلةِ المدى.",
"<b>الاستعمالاتُ الطبية</b>: يستعملُ اليود-١٣١ لتشخيصِ المشاكلِ المتعلّقةِ بالغدّةِ الدرقيةِ التي في أسفلِ الرقبة (الشكل ٢٣)؛ فالغدّةُ الدرقيةُ السليمةُ تمتصُّ اليودَ لتنتجَ هرموناتٍ لتنظيمِ عملياتِ الأيض، ويُعطى المريضُ جرعةً من اليودِ المشعّ ثم تُصوَّرُ الغدّةُ بكاميرا أشعةِ جاما. كما يُستخدمُ التكنيتيوم-٩٩ الذي عمرُ النصفِ له ستُّ ساعاتٍ لتتبّعِ عملياتِ الجسمِ المختلفة، وتُكتشَفُ به الأورامُ والتمزّقاتُ أو الكسورُ بوضوح؛ لأنّ النظائرَ تُظهرُ صورًا واضحةً عن الأماكنِ التي تنمو فيها الخلايا بسرعة.",
"<b>الاستعمالاتُ البيئية</b>: يُستخدمُ العديدُ من العناصرِ المشعّةِ في البيئةِ بوصفِها متتبّعات؛ ومن هذه الاستخداماتِ حقنُ الفوسفور-٣٢ المشعِّ في جذورِ النباتاتِ لتعرّفِ مدى استفادةِ هذه النباتاتِ من الفوسفورِ خلالَ عمليتي النموِّ والتكاثر. وتُستخدمُ النظائرُ المشعّةُ أيضًا في المبيداتِ الحشرية لمعرفةِ تأثيرِ المبيدِ في النظامِ البيئي، وفي تتبّعِ مصادرِ المياهِ ومعرفةِ كميتِها، وهذه التقنيةُ تُستخدمُ للبحثِ عن مصادرِ المياهِ في الكثيرِ من الدولِ المتقدّمةِ والتي تقعُ في مناطقَ جافّة."
],
