"t": "جدولُ مندليف للعناصر: نشرَ العالِمُ الروسيُّ ديمتري مندليف عام ١٨٦٩م النسخةَ الأولى من جدولِه الدوري (الشكل ١)، وقد رتّبَ العناصرَ حسب تزايدِ أعدادِها الكتلية، ولاحظَ مندليف النمطيةَ في الترتيب؛ حيث يكونُ للعناصرِ التي في مجموعةٍ واحدةٍ خصائصُ متشابهة."
