"t": "تمَّ ترتيبُ العناصرِ في الجدولِ الدوريِّ الحديثِ حسب تزايدِ أعدادِها الذرّية، ووُضعتِ العناصرُ في سبعِ دوراتٍ مرقّمة (١–٧). والدورةُ صفٌّ أفقيٌّ في الجدولِ الدوريِّ يحتوي على عناصرَ تتغيّرُ خصائصُها بشكلٍ تدريجيٍّ يمكنُ توقّعُه. كما يتكوّنُ الجدولُ الدوريُّ من ١٨ عمودًا، وكلُّ عمودٍ يتكوّنُ من مجموعةٍ أو عائلةٍ من العناصر، وعناصرُ المجموعةِ الواحدةِ تتشابهُ في خصائصِها الفيزيائيةِ والكيميائية."
