"body": [
"تمَّ ترتيبُ العناصرِ في الجدولِ الدوريِّ الحديثِ حسب تزايدِ أعدادِها الذرّية، ووُضعتِ العناصرُ في سبعِ دوراتٍ مرقّمة (١–٧). و<b>الدورةُ</b> صفٌّ أفقيٌّ في الجدولِ الدوريِّ يحتوي على عناصرَ تتغيّرُ خصائصُها بشكلٍ تدريجيٍّ يمكنُ توقّعُه. كما يتكوّنُ الجدولُ الدوريُّ من ١٨ عمودًا، وكلُّ عمودٍ يتكوّنُ من مجموعةٍ أو عائلةٍ من العناصر، وعناصرُ <b>المجموعةِ</b> الواحدةِ تتشابهُ في خصائصِها الفيزيائيةِ والكيميائية.",
"<b>مناطقُ الجدولِ الدوري</b>: يمكنُ تقسيمُ الجدولِ الدوريِّ إلى قطاعات (الشكل ٢)؛ تشملُ المنطقةُ الأولى المجموعتين ١ و٢، والمجموعاتِ ١٣–١٨، وتُسمّى هذه المنطقةُ من عناصرِ المجموعاتِ الثماني <b>العناصرَ الممثّلة</b>، وفيها فلزّاتٌ ولافلزّاتٌ وأشباهُ فلزّات. أمّا العناصرُ في المجموعاتِ ٣–١٢ فتُسمّى <b>العناصرَ الانتقالية</b>، وجميعُها فلزّات.",
"هناك عناصرُ انتقاليةٌ داخليةٌ موجودةٌ أسفلَ الجدولِ الدوري، ومنها مجموعتا الأكتينيدات واللانثانيدات؛ لأنّ إحداهما تتبعُ عنصرَ اللانثانيوم وعددُه الذرّيُّ ٥٧، والأخرى تتبعُ عنصرَ الأكتينيوم الذي عددُه الذرّيُّ ٨٩.",
"يدلُّ لونُ صندوقِ كلِّ عنصرٍ على ما إذا كان فلزًّا أو شبهَ فلزٍّ أو لافلزًّا، والرموزُ الثلاثةُ العليا تدلُّ على حالةِ العنصرِ في درجةِ حرارةِ الغرفة (غاز، سائل، صلب)، بينما يدلُّ الرمزُ الرابعُ على العناصرِ المصنّعة. والرقمُ المحاطُ بقوسين هو العددُ الكتليُّ للنظيرِ الأطولِ عمرًا للعنصر."
],
