"t": "الفلزّات: إذا تمعّنتَ في الجدولِ الدوريِّ ستجدُه ملوّنًا بألوانٍ مختلفةٍ تمثّلُ العناصرَ الفلزيةَ وغيرَ الفلزيةِ وأشباهَ الفلزّات (الشكل ٣). وجميعُ الفلزّاتِ صلبةٌ ما عدا الزئبق، ودرجةُ انصهارِ معظمِها عالية. والفلز عنصرٌ لامع، أي لديه قدرةٌ على عكسِ الضوء، وموصلٌ جيّدٌ للكهرباءِ والحرارة، وقابلٌ للطرقِ والسحب."
