"<b>مفتاحُ العنصر</b>: يُمثَّلُ كلُّ عنصرٍ في الجدولِ الدوريِّ بصندوقٍ يُسمّى مفتاحَ العنصر (الشكل ٤)، وهذا المفتاحُ يبيّنُ اسمَ العنصرِ وعددَه الذرّيَّ ورمزَه وكتلتَه الذرّيةَ وحالتَه (صلب أو سائل أو غازي) عند درجةِ حرارةِ الغرفة. ونلاحظُ أنّ جميعَ الغازات – ما عدا الهيدروجين – تقعُ يمينَ الجدول، وأنّ العنصرين السائلين في الجدولِ الدوريِّ هما البروم والزئبق.",
"<b>رموزُ العناصر</b>: تُكتبُ رموزُ العناصرِ بحرفٍ أو حرفين، وتكونُ غالبًا مبنيةً أو مشتقّةً من اسمِ العنصر؛ فالحرفُ V اختصارٌ لاسمِ العنصرِ Vanadium. وقد يُشتقُّ الرمزُ من الاسمِ اللاتينيِّ أو الإغريقيِّ للعنصر، أو من أسماءِ العلماءِ أو بلدانِهم كالفرانسيوم Fr والبولونيوم Po (الجدول ١)."
