"body": [
"<b>المجموعةُ ١٥ – مجموعةُ النيتروجين</b>: نجدُ في أعلى المجموعةِ الخامسةَ عشرةَ عنصرين لافلزّين هما النيتروجينُ والفوسفور، وهما ضروريان للمخلوقاتِ الحيّة، ويدخلان في تركيبِ الموادِّ الحيويةِ التي تعملُ على تخزينِ المعلوماتِ الجينيةِ والطاقةِ في الجسم. ورغمَ أنّ أكثرَ من ٨٠٪ من الهواءِ الذي نتنفّسُه نيتروجين إلا أنّنا لا نستطيعُ أخذَ حاجةِ الجسمِ من النيتروجين عند استنشاقِه؛ إذ يجبُ أوّلًا أن تحوّلَ البكتيريا غازَ النيتروجين إلى موادَّ يسهلُ على جذورِ النباتاتِ امتصاصُها، ثم يأخذُ الجسمُ حاجتَه منه بتناولِه للنبات.",
"يحتوي غازُ الأمونيا على النيتروجين والهيدروجين، ويُستخدمُ منظّفًا ومطهّرًا للجراثيم، وتُضافُ الأمونيا السائلةُ إلى التربةِ بوصفِها سمادًا، وتُستخدمُ في تجميدِ الطعام وفي صناعةِ النايلون المستخدمِ في المظلّات (الشكل ٨). وهناك نوعان من الفوسفور هما الأحمرُ والأبيض، والأبيضُ أكثرُ نشاطًا ولا يجبُ أن يتعرّضَ للأكسجين حتى لا ينفجر؛ لذلك تُصنعُ رؤوسُ أعوادِ الثقابِ من الفوسفورِ الأحمرِ الأقلِّ نشاطًا. ومركّباتُ الفوسفور مكوّنٌ أساسيٌّ في صحّةِ الأسنانِ والعظام، ونجدُه من المكوّناتِ الأساسيةِ للأسمدة (الشكل ٩).",
"<b>المجموعةُ ١٦ – عائلةُ الأكسجين</b>: أوّلُ عنصرين فيها هما الأكسجينُ والكبريت، وهما أساسيان في الحياة، بينما العناصرُ الأثقلُ في المجموعةِ هما التيلوريوم والبولونيوم، وهما أشباهُ فلزّات. يكوّنُ الأكسجينُ حوالي ٢٠٪ من الغلافِ الجوي، ويحتاجُ الجسمُ إليه لإنتاجِ الطاقةِ من الغذاء، وهو ضروريٌّ للاشتعال؛ وتكمنُ أهميةُ استخدامِ الرغوةِ في إطفاءِ الحرائقِ أنّها تعزلُ الأكسجينَ عن الموادِّ المشتعلة (الشكل ١٠). والأوزون هو الشكلُ الأقلُّ شيوعًا للأكسجين، يتكوّنُ في طبقاتِ الجوِّ العليا، وهو ضروريٌّ لحمايةِ المخلوقاتِ الحيّةِ من الإشعاعاتِ الشمسيةِ الضارّة.",
"أمّا الكبريتُ فهو لافلزٌّ صلبٌ أصفرُ اللون، يُستخدمُ بكمياتٍ كبيرةٍ في صناعةِ حمضِ الكبريتيك، الحمضِ الأكثرِ استخدامًا في العالم. أمّا السيلينيوم فهو موصلٌ للكهرباءِ عند تعرّضِه للضوء، ولذلك يُستخدمُ في الخلايا الشمسيةِ وعدّاداتِ الضوء."
],
