"t": "المجموعةُ ١٨ – الغازاتُ النبيلة: تُسمّى عناصرُ المجموعةِ ١٨ الغازاتِ النبيلة؛ لأنّها توجدُ في الطبيعةِ منفردة، ونادرًا ما تتّحدُ مع عناصرَ أخرى بسببِ نشاطِها القليلِ جدًّا. فالهيليوم عنصرٌ أقلُّ كثافةً من الهواء، ولا يشتعل؛ ولذلك يُستخدمُ في ملءِ البالوناتِ والمناطيد التي تحملُ كاميراتٍ لتصويرِ الأحداثِ الرياضية، أو أجهزةً خاصّةً لقياسِ عناصرِ الطقس. ورغمَ أنّ الهيدروجينَ أخفُّ من الهيليوم إلا أنّ الهيليومَ يُستخدمُ أكثر؛ لأنّه لا يشتعل، ممّا يعني أنّه آمن."
