"body": [
"<b>المجموعةُ ١٧ – مجموعةُ الهالوجينات</b>: جميعُ عناصرِ هذه المجموعةِ لافلزّات ما عدا الأستاتين؛ فهو شبهُ فلزٍّ مشعّ. وقد سُمّيتْ <b>بالهالوجينات</b> وتعني «مكوّناتِ الأملاح»؛ فنجدُ مثلًا أنّ ملحَ الطعامِ أو كلوريدَ الصوديومِ مادةٌ تتكوّنُ من الصوديوم والكلور، وتكوّنُ جميعُ عناصرِ هذه المجموعةِ أملاحًا مشابهةً عند اتّحادِها مع الصوديوم أو مع أيِّ عنصرٍ من عناصرِ الفلزّاتِ القلوية.",
"أكثرُ عناصرِ المجموعةِ نشاطًا هو الفلور ثم الكلور فالبروم، ثم اليودُ الذي يُعدُّ أقلَّها نشاطًا. ويوضّحُ الشكل ١١ بعضَ استخداماتِ الهالوجينات؛ فالكلورُ يُضافُ إلى مياهِ المسابحِ للتعقيمِ وقتلِ البكتيريا، وتحتاجُ أجهزةُ جسمِك إلى اليود (ملحٌ باليود).",
"<b>المجموعةُ ١٨ – الغازاتُ النبيلة</b>: تُسمّى عناصرُ المجموعةِ ١٨ <b>الغازاتِ النبيلة</b>؛ لأنّها توجدُ في الطبيعةِ منفردة، ونادرًا ما تتّحدُ مع عناصرَ أخرى بسببِ نشاطِها القليلِ جدًّا. فالهيليوم عنصرٌ أقلُّ كثافةً من الهواء، ولا يشتعل؛ ولذلك يُستخدمُ في ملءِ البالوناتِ والمناطيد التي تحملُ كاميراتٍ لتصويرِ الأحداثِ الرياضية، أو أجهزةً خاصّةً لقياسِ عناصرِ الطقس. ورغمَ أنّ الهيدروجينَ أخفُّ من الهيليوم إلا أنّ الهيليومَ يُستخدمُ أكثر؛ لأنّه لا يشتعل، ممّا يعني أنّه آمن.",
"<b>استخداماتُ الغازاتِ النبيلة</b>: يُستخدمُ غازُ النيون وباقي الغازاتِ النبيلةِ في اللوحاتِ الإعلانية (الشكل ١٢)؛ فعندما يمرُّ التيارُ الكهربائيُّ في الأنابيبِ التي تحتوي على هذه الغازاتِ تتوهّجُ الأنابيبُ بألوانٍ مختلفةٍ حسب نوعِ الغاز. والأرجون هو الغازُ النبيلُ الأكثرُ توافرًا في الطبيعة، ويُستخدمُ الكريبتون مع النيتروجين في مصابيحِ الإنارةِ العادية؛ لأنّ هذه الغازاتِ تحفظُ الفتيلَ من الاحتراق. ونجدُ في نهايةِ المجموعةِ الرادون، وهو غازٌ مشعٌّ جدًّا ينتجُ بشكلٍ طبيعيٍّ عند تحلّلِ اليورانيوم في التربةِ والصخور، وهو غازٌ مضرٌّ جدًّا."
],
