"t": "تُسمّى المجموعاتُ ٣–١٢ في الجدولِ الدوريِّ العناصرَ الانتقالية، وجميعُها فلزّات. وإذا تتبّعنا هذه الفلزّاتِ من اليسارِ إلى اليمين سنجدُ أنّ خصائصَها لا يحكمُها نمطُ تغيّرٍ واضح مقارنةً بالتغيّرِ الذي يحدثُ للعناصرِ الممثّلة. وتكونُ معظمُ العناصرِ الانتقاليةِ متّحدةً مع عناصرَ أخرى على هيئةِ خامات، وقد يكونُ بعضُها حرًّا مثلَ الذهبِ والفضة."
