"t": "هناك سلسلتان من العناصرِ الانتقاليةِ الداخلية، تمتدُّ الأولى من السيريوم إلى اللوتيتيوم، وتُسمّى اللانثانيدات أو العناصرَ الترابيةَ النادرة؛ وذلك لأنّ الاعتقادَ السائدَ آنذاك أنّها قليلةُ الوجود، وتوجدُ عادةً متّحدةً مع الأكسجينِ في القشرةِ الأرضية. أمّا السلسلةُ الثانيةُ فتمتدُّ من الثوريوم إلى اللورنسيوم، وتُسمّى الأكتينيدات."
