"t": "اللانثانيدات فلزّاتٌ لينةٌ يمكنُ قطعُها بالسكّين، ولكنّها متشابهة، حيث يصعبُ فصلُها عندما توجدُ في خامٍ واحد، ولقد اعتُقدَ قديمًا أنّها نادرةُ الوجود، إلا أنّ القشرةَ الأرضيةَ تحتوي في الواقعِ من السيريوم أكثرَ من الرصاص؛ فالسيريوم يكوّنُ ٥٠٪ من سبيكةِ الميشميتال، التي نجدُها في حجرِ الولّاعة (الشكل ١٦)."
